import{_ as e,c as t,o as r,a0 as n}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Hurtig reference til mentalt spil","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/da/summary-sheet.md","filePath":"public/downloads/da/summary-sheet.md"}');const l=e({name:"public/downloads/da/summary-sheet.md"},[["render",function(e,i,l,s,o,d){return r(),t("div",null,[...i[0]||(i[0]=[n('<h1 id="hurtig-reference-til-mentalt-spil" tabindex="-1">Hurtig reference til mentalt spil <a class="header-anchor" href="#hurtig-reference-til-mentalt-spil" aria-label="Permalink to &quot;Hurtig reference til mentalt spil&quot;">​</a></h1><p><strong>Pétanque Academy - Resumé på én side</strong></p><hr><h2 id="zone-flowtilstanden" tabindex="-1">Zone-/flowtilstanden <a class="header-anchor" href="#zone-flowtilstanden" aria-label="Permalink to &quot;Zone-/flowtilstanden&quot;">​</a></h2><p><strong>To sindstilstande:</strong></p><table tabindex="0"><thead><tr><th>Planlægningstilstand</th><th>Udførelsestilstand</th></tr></thead><tbody><tr><td>Analyser terræn</td><td>Stol på din krop</td></tr><tr><td>Vælg strategi</td><td>Tænk ikke</td></tr><tr><td>Vurder risici</td><td>Nutiden</td></tr><tr><td>Træf beslutninger</td><td>Automatisk udførelse</td></tr></tbody></table><p><strong>Skiftet:</strong> Planlæg før, flow under</p><hr><h2 id="indre-kritiker-vs-indre-coach" tabindex="-1">Indre kritiker vs. indre coach <a class="header-anchor" href="#indre-kritiker-vs-indre-coach" aria-label="Permalink to &quot;Indre kritiker vs. indre coach&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Indre kritiker ❌</th><th>Indre coach ✅</th></tr></thead><tbody><tr><td>&quot;Det var forfærdeligt!&quot;</td><td>&quot;Hvad kan jeg lære?&quot;</td></tr><tr><td>&quot;Du laver altid fejl&quot;</td><td>&quot;Næste skud, en frisk start&quot;</td></tr><tr><td>&quot;Alle ser dig fejle&quot;</td><td>&quot;Jeg har gjort det før&quot;</td></tr><tr><td>&quot;Du er ikke god nok&quot;</td><td>&quot;Stol på processen&quot;</td></tr></tbody></table><p><strong>Omdrul:</strong> Pause → Omdrul → Nulstil → Fokusér igen</p><hr><h2 id="_3-andedrætsnulstilling" tabindex="-1">3-åndedrætsnulstilling <a class="header-anchor" href="#_3-andedrætsnulstilling" aria-label="Permalink to &quot;3-åndedrætsnulstilling&quot;">​</a></h2><p><strong>Brug efter fejl eller pres:</strong></p><ol><li><strong>Åndedræt 1:</strong> Bemærk spænding (hvor?)</li><li><strong>Åndedræt 2:</strong> Slip spændinger (giv slip)</li><li><strong>Åndedræt 3:</strong> Fokusér igen (dette billede, nu)</li></ol><hr><h2 id="rutine-før-optagelse" tabindex="-1">Rutine før optagelse <a class="header-anchor" href="#rutine-før-optagelse" aria-label="Permalink to &quot;Rutine før optagelse&quot;">​</a></h2><p><strong>Samme rutine, hvert skud:</strong></p><ol><li><strong>Visualiser</strong> - Se billedet</li><li><strong>Træk vejret</strong> - En dyb indånding</li><li><strong>Anker</strong> - Rør ved kuglen, føl vægten</li><li><strong>Udfør</strong> - Stol på og kast</li></ol><hr><h2 id="protokol-for-fejlretning" tabindex="-1">Protokol for fejlretning <a class="header-anchor" href="#protokol-for-fejlretning" aria-label="Permalink to &quot;Protokol for fejlretning&quot;">​</a></h2><p><strong>Efter et dårligt skud:</strong></p><ol><li><strong>Anerkendelse</strong> - &quot;Gik ikke som planlagt&quot;</li><li><strong>Udgivelse</strong> - Fysisk nulstilling (ryst det af)</li><li><strong>Refokusér</strong> - &quot;Næste skud er nyt&quot;</li><li><strong>Udfør</strong> - Stol på din rutine</li></ol><hr><h2 id="denne-uges-øvelse" tabindex="-1">Denne uges øvelse <a class="header-anchor" href="#denne-uges-øvelse" aria-label="Permalink to &quot;Denne uges øvelse&quot;">​</a></h2><p><strong>Vælg ÉN teknik:</strong></p><ul><li>[ ] 3-Åndedrætsnulstilling efter hver fejl</li><li>[ ] Rutine før kast ved hvert kast</li><li>[] Omformuler én Indre Kritiker-tanke per session</li><li>[ ] Øvelse i skiftplanlægning → udførelsestilstand</li></ul><hr><h2 id="spor-dine-fremskridt" tabindex="-1">Spor dine fremskridt <a class="header-anchor" href="#spor-dine-fremskridt" aria-label="Permalink to &quot;Spor dine fremskridt&quot;">​</a></h2><p><strong>Meddelelse:</strong></p><ul><li>Hvornår føler du dig mest i flow?</li><li>Hvad trigger din indre kritiker?</li><li>Hvilken teknik hjælper dig mest?</li><li>Hvordan ændrer din præstation sig?</li></ul><hr><h2 id="nøgleprincipper" tabindex="-1">Nøgleprincipper <a class="header-anchor" href="#nøgleprincipper" aria-label="Permalink to &quot;Nøgleprincipper&quot;">​</a></h2><ol><li><strong>Flow er tilgængeligt</strong> - Du kan lære at træde ind i det konsekvent</li><li><strong>Din indre stemme betyder noget</strong> - Coach dig selv, kritiser ikke</li><li><strong>Enkle værktøjer virker</strong> - 3 vejrtrækninger, en rutine, en nulstilling</li><li><strong>Øvelse er nøglen</strong> - Mentale færdigheder kræver træning ligesom tekniske færdigheder</li></ol><hr><h2 id="ressourcer" tabindex="-1">Ressourcer <a class="header-anchor" href="#ressourcer" aria-label="Permalink to &quot;Ressourcer&quot;">​</a></h2><p><strong>Fortsæt med at lære på carreau.app:</strong></p><ul><li>Zonen - Dybdegående dyk ned i flowtilstanden</li><li>Mental styrke - Avanceret preshåndtering</li><li>Målskabelon - Strukturer din udvikling</li><li>Dagbogsskabelon - Spor dine fremskridt</li></ul><hr><p><strong>Husk:</strong> Mental træning handler ikke om positiv tænkning. Det handler om praktiske teknikker, der hjælper dig med at opnå din bedste præstation under pres.</p><hr><p><em>Pétanque Academy - Elite Player Development</em><em>carreau.app</em></p>',42)])])}]]);export{i as __pageData,l as default};
